//! Apple Notes body and table decoding (PLAN.md §3.2).
//!
//! - [`body`] (WP-A): base64 → gzip/zlib/raw → `NoteStoreProto` → [`proto::Note`].
//! - [`table`] (WP-B): `MergeableDataEncrypted` → [`Table`].

pub mod body;
pub mod table;

/// Types generated by prost from `vendor/apple_cloud_notes_parser/notestore.proto`.
pub mod proto {
    // notestore.proto has no `package`, so prost writes `_.rs`.
    include!(concat!(env!("OUT_DIR"), "/_.rs"));
}

pub use body::{decode_note, inflate, inflate_bytes, plain_text};
pub use notes_model::DecodeError;
pub use table::{Table, decode_table};
